#extract_clips.py
import cv2
import os
import csv

RAW_DIR = "data/raw"
CLIPS_DIR = "data/clips"
LABELS_FILE = "data/labels.csv"

#############################################
# Added to read timestamps from a JSON file generated by viewer.py
import json
TIMESTAMPS_FILE = "data/timestamps.json"
if os.path.exists(TIMESTAMPS_FILE):
    with open(TIMESTAMPS_FILE, "r") as f:
        pairs = json.load(f)

print(f"Loaded {len(pairs)} timestamp pairs from {TIMESTAMPS_FILE}")
print("For each penalty, enter:")
print("  Direction (L/C/R) from the keeper's perspective")
print("  Foot: l (left) / r (right) used to take the penalty\n")

os.makedirs(CLIPS_DIR, exist_ok=True)



import subprocess
# attempting to useuse ffmpeg directly via Python's subprocess 
def extract_clip(video_path, start_sec, end_sec, clip_id):
    output_path = os.path.join(CLIPS_DIR, f"clip_{clip_id:03d}.mp4")
    duration = end_sec - start_sec
    
    subprocess.run([
        "ffmpeg", "-y",
        "-ss", str(start_sec),
        "-i", video_path,
        "-t", str(duration),
        "-c:v", "libx264",   # H.264, universally supported
        "-c:a", "aac",
        "-loglevel", "error", # suppress ffmpeg spam
        output_path
    ], check=True)
    
    print(f"Saved: {output_path}")
    return output_path

with open(LABELS_FILE, "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["clip_id", "clip_path", "direction", "foot", "start_time", "end_time"])

    video_file = os.path.join(RAW_DIR, "All Penalties In Regular Time FIFA World Cup 2026.mp4")

    for i, (start, end) in enumerate(pairs):
        print(f"\nProcessing Penalty {i+1}: Start={start}s, End={end}s")
        direction = input(f"Penalty {i+1}: Enter direction (L/C/R): ").strip().upper()
        foot = input(f"Penalty {i+1}: Enter foot used (l/r): ").strip().lower()
        foot = "left" if foot == "l" else "right" if foot == "r" else "unknown"


        path = extract_clip(video_file, start, end, i)
        writer.writerow([i, path, direction, foot, start, end])
        print(f"Saved Penalty {i+1}: Direction={direction}, Foot={foot}, Start={start}s, End={end}s")

print(f"\nExtracted {len(pairs)} clips. Labels saved to {LABELS_FILE}") 